def shipping_cost(weight):
    """Return five currency units per unit weight; reject nonpositive weights."""
    if weight <= 0:
        raise ValueError("weight must be positive")
    return weight * 5

class Pricing {
public:
    int shipping_cost(int weight) { return weight * 5; }
};

